  #[test]
  fn test_compression_on_simple_data() {
      let data = (0..=CHUNK_SIZE*11 as u64).collect::<Vec<_>>();
      let (estimate, actual_compression) =
          create_and_validate(&data, "simple monotonically");
      println!("actual compression {} estimate {} data len {}", actual_compression, estimate, data.len());
      assert!(actual_compression < 0.2);
      assert!(estimate < 0.20);
      assert!(estimate > 0.15);
      assert!(actual_compression > 0.1);
  }
